	private static List<String> seed(SailRepository repository, boolean path) {
		List<String> expected = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.begin();
			if (path) {
				IRI edge = vf.createIRI(NS + "edge");
				for (int level = 0; level < 96; level++) {
					for (int lane = 0; lane < 2; lane++) {
						IRI target = vf.createIRI(NS + "level" + level + ':' + lane);
						expected.add(target.stringValue());
						if (level == 0) {
							connection.add(vf.createIRI(NS + "root"), edge, target);
						} else {
							for (int parent = 0; parent < 2; parent++) {
								connection.add(vf.createIRI(NS + "level" + (level - 1) + ':' + parent), edge, target);
							}
						}
					}
				}
			} else {
				IRI type = vf.createIRI(NS + "Root");
				for (int root = 0; root < 96; root++) {
					IRI subject = vf.createIRI(NS + "s" + root);
					for (IRI predicate : List.of(RDF.TYPE, vf.createIRI(NS + "payload"), vf.createIRI(NS + "link"))) {
						IRI object = predicate.equals(RDF.TYPE) ? type : vf.createIRI(NS + "o" + root);
						connection.add(subject, predicate, object);
						expected.add(
								subject.stringValue() + '|' + predicate.stringValue() + '|' + object.stringValue());
					}
				}
			}
			connection.commit();
		}
		return expected;
	}

	private static String canonical(BindingSet row, boolean path) {
		return path ? row.getValue("o").stringValue()
				: row.getValue("s").stringValue() + '|' + row.getValue("p").stringValue() + '|'
						+ row.getValue("o").stringValue();
	}

	private static boolean hasConflict(Throwable failure) {
		for (Throwable cause = failure; cause != null; cause = cause.getCause()) {
			if (cause instanceof SailConflictException) {
				return true;
			}
		}
		return false;
	}
